export function getScenarioRealWorldStory(
  scenarioId: string
): ScenarioRealWorldStoryBundle | null {
  if (scenarioId === 'process-hollowing') return null;
  return SCENARIO_REAL_WORLD_STORIES[scenarioId] ?? null;
}
